// named reports whether some route of this server could answer a request for
// path: exactly, as a subtree ("/api/links" is covered by "/api/") or through
// a wildcard ("GET /{slug}" covers "/abc123"). Auth uses it to find the
// request no pattern of this server covers at all. It asks a copy of the mux,
// which answers what a real request would except that HEAD does not follow GET
// there; named folds that in itself.
func (s *Server) named(method, path string) bool {
	if method == http.MethodHead {
		method = http.MethodGet
	}
	// The request is built to be asked about and never sent anywhere:
	// NewRequest makes no connection, and the host names none that resolves.
	// #nosec G704 -- the URL goes to ServeMux.Handler for routing only; this
	// code never issues a request, so there is no server-side fetch at all.
	r, err := http.NewRequestWithContext(context.Background(), method, "http://short.example"+path, nil)
	if err != nil {
		return false
	}
	for _, m := range []string{"", method} {
		// A request built with no method is a GET to ServeMux, so ask whether
		// a bare pattern covers the path by looking for one first.
		if m == "" && !s.hasBarePattern() {
			continue
		}
		ask := *r
		ask.Method = m
		if _, matched := s.probe().Handler(&ask); matched != "" {
			return true
		}
	}
	return false
}

// hasBarePattern reports whether any route of this server names no method:
// only such a pattern answers a request whose method none of them names.
func (s *Server) hasBarePattern() bool {
	for _, p := range s.patterns {
		if _, _, hasMethod := strings.Cut(p, " "); !hasMethod {
			return true
		}
	}
	return false
}

// probe is a copy of the mux holding only the routes registered so far, so
// that asking it about a path cannot change what this server serves.
func (s *Server) probe() *http.ServeMux {
	mux := http.NewServeMux()
	for _, p := range s.patterns {
		if err := tryRegister(mux, p); err != nil {
			continue
		}
	}
	return mux
}

