package server

import (
	"context"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"testing"

	"git.aisoftwarefactory.world/linkshort3/linkshort3/internal/store"
)

func TestDbgG(t *testing.T) {
	dir := filepath.Join(t.TempDir(), "data")
	_ = os.MkdirAll(dir, 0o755)
	srv := httptest.NewServer(New(Config{DataDir: dir}))
	req, _ := http.NewRequest(http.MethodGet, srv.URL+"/nope123", nil)
	res, err := srv.Client().Do(req)
	if err != nil { t.Fatal(err) }
	res.Body.Close()
	srv.Close()
	for _, name := range []string{"links.db-wal", "links.db-shm"} {
		if _, err := os.Stat(filepath.Join(dir, name)); err == nil {
			t.Logf("still there: %s", name)
		} else {
			t.Logf("gone: %s", name)
		}
	}
	st, err := store.Open(dir)
	if err != nil { t.Fatal(err) }
	l, err := st.GetLinkBySlug(context.Background(), "nope123")
	t.Logf("reopen read: %v %v", l, err)
	_ = st.Close()
	for _, name := range []string{"links.db-wal", "links.db-shm"} {
		if _, err := os.Stat(filepath.Join(dir, name)); err == nil {
			t.Logf("after reopen close still there: %s", name)
		} else {
			t.Logf("after reopen close gone: %s", name)
		}
	}
}
EOF
go test ./internal/server/ -run 'TestDbgG' -v -count=1 2>&1 | tail -10

