package server

import (
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"testing"
)

func TestDbgH(t *testing.T) {
	for _, only := range []bool{true, false} {
		dir := filepath.Join(t.TempDir(), "data")
		_ = os.MkdirAll(dir, 0o755)
		srv := httptest.NewServer(New(Config{DataDir: dir}))
