package server

import (
	"net/http"
	"os"
	"path/filepath"
	"testing"
)

func TestDbgI(t *testing.T) {
	dir := filepath.Join(t.TempDir(), "data")
	_ = os.MkdirAll(dir, 0o755)
	h := New(Config{DataDir: dir})
	for _, p := range []string{"/api/me", "/api/nothing-here", "/nope123", "/zzzzzzz"} {
		req, _ := http.NewRequest(http.MethodGet, "http://x"+p, nil)
		w := &statusWriter{hdr: http.Header{}}
		h.ServeHTTP(w, req)
		t.Logf("%s -> %d", p, w.code)
	}
}

type statusWriter struct {
	hdr  http.Header
	code int
}

func (w *statusWriter) Header() http.Header { return w.hdr }
func (w *statusWriter) Write(b []byte) (int, error) { return len(b), nil }
func (w *statusWriter) WriteHeader(c int) { w.code = c }
EOF
go test ./internal/server/ -run 'TestDbgI' -v -count=1 2>&1 | tail -8

