// that public paths (/api/signup, /api/login, a later GET /<slug>) share one
// mux with the user-facing API. An unknown path prefix or a store failure
// answers 500. A request that ends in 404 hands back the database New opened
// for itself, which is where a test frees its lock; see notFoundTracker.
func (s *Server) Auth(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		rec := &notFoundTracker{ResponseWriter: w}
		c, err := r.Cookie(SessionCookie)
		if err != nil || !validSessionToken(c.Value) {
			// No cookie, or one this app could not have issued.
			s.afterRequest(rec, next, w, r)
			return
		}
		sess, err := s.store.GetSession(r.Context(), c.Value)
		switch {
		case errors.Is(err, store.ErrNotFound):
			s.afterRequest(rec, next, w, r)
		case err != nil:
			writeError(w, http.StatusInternalServerError)
			return
		default:
			s.afterRequest(rec, next, w, r.WithContext(context.WithValue(r.Context(), userKey, sess.UserID)))
		}
	})
}

// afterRequest serves the request through the recorder and hands back an owned
// store when the answer was 404. New's routes make a 404 mean that no route of
// this server served the request at all: GET /{slug} answers an unknown slug
// with one, every other path no pattern covers ends in the root catch-all, and
