}

func (s *SQLiteStore) ListLinksByUser(ctx context.Context, userID int64) ([]*Link, error) {
	rows, err := s.db.QueryContext(ctx,
		`SELECT `+linkColumns+` FROM links WHERE user_id = ? ORDER BY created_at DESC, id DESC`, userID)
	if err != nil {
		return nil, err
	}
	defer func() { _ = rows.Close() }()
	links := []*Link{}
	for rows.Next() {
		l, err := scanLink(rows)
		if err != nil {
			return nil, err
		}
		links = append(links, l)
	}
	return links, rows.Err()
}

func (s *SQLiteStore) DeleteLink(ctx context.Context, userID int64, slug string) error {
	res, err := s.db.ExecContext(ctx, `DELETE FROM links WHERE slug = ? AND user_id = ?`, slug, userID)
	if err != nil {
		return err
	}
	n, err := res.RowsAffected()
	if err != nil {
		return err
	}
	if n == 0 {
		return ErrNotFound
	}
	return nil
}

func (s *SQLiteStore) IncrementClick(ctx context.Context, slug string, now time.Time) error {
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback() }()
	res, err := tx.ExecContext(ctx, `UPDATE links SET total_clicks = total_clicks + 1 WHERE slug = ?`, slug)
	if err != nil {
		return err
	}
	if n, err := res.RowsAffected(); err != nil {
		return err
	} else if n == 0 {
		return ErrNotFound
	}
	if _, err := tx.ExecContext(ctx,
		`INSERT INTO clicks (link_id, day, count)
		   SELECT id, ?, 1 FROM links WHERE slug = ?
		 ON CONFLICT (link_id, day) DO UPDATE SET count = count + 1`,
		day(now), slug); err != nil {
		return err
	}
	return tx.Commit()
}

