// path it picks; maybeCloseStore does nothing when the caller passed a Store.
func (s *Server) afterRequest(rec *notFoundTracker, next http.Handler, w http.ResponseWriter, r *http.Request) {
	next.ServeHTTP(rec, r)
	if rec.notFound {
		s.maybeCloseStore()
	}
